// Hello Cesium 示例
// 初始化Cesium Viewer
const viewer = new Cesium.Viewer('cesiumContainer', {
    terrain: Cesium.Terrain.fromWorldTerrain(),
    baseLayer: Cesium.ImageryLayer.fromProviderAsync(Cesium.IonImageryProvider.fromAssetId(2))
});

// 设置默认视角
viewer.camera.setView({
    destination: Cesium.Cartesian3.fromDegrees(116.4074, 39.9042, 1000),
    orientation: {
        heading: Cesium.Math.toRadians(0),
        pitch: Cesium.Math.toRadians(-45),
        roll: 0.0
    }
});

// 添加一个基本的实体
const entity = viewer.entities.add({
    position: Cesium.Cartesian3.fromDegrees(116.4074, 39.9042, 100),
    point: {
        pixelSize: 10,
        color: Cesium.Color.RED,
        outlineColor: Cesium.Color.WHITE,
        outlineWidth: 2
    },
    label: {
        text: '北京',
        font: '14pt sans-serif',
        heightReference: Cesium.HeightReference.CLAMP_TO_GROUND,
        verticalOrigin: Cesium.VerticalOrigin.BOTTOM
    }
});

viewer.zoomTo(entity);

