// Cesium相机控制示例
const viewer = new Cesium.Viewer('cesiumContainer', {
    terrain: Cesium.Terrain.fromWorldTerrain()
});

// 设置初始视角
viewer.camera.setView({
    destination: Cesium.Cartesian3.fromDegrees(116.4074, 39.9042, 1000),
    orientation: {
        heading: 0.0,
        pitch: -Cesium.Math.PI_OVER_TWO,
        roll: 0.0
    }
});

// 相机控制函数
function flyToLocation(longitude, latitude, height, duration = 3) {
    viewer.camera.flyTo({
        destination: Cesium.Cartesian3.fromDegrees(longitude, latitude, height),
        orientation: {
            heading: 0.0,
            pitch: -Cesium.Math.PI_OVER_TWO,
            roll: 0.0
        },
        duration: duration,
        complete: function() {
            console.log('飞行完成');
        }
    });
}

// 添加控制按钮
const locations = [
    { name: '北京', lon: 116.4074, lat: 39.9042, height: 1000 },
    { name: '上海', lon: 121.4737, lat: 31.2304, height: 1000 },
    { name: '广州', lon: 113.2644, lat: 23.1291, height: 1000 },
    { name: '深圳', lon: 114.0579, lat: 22.5431, height: 1000 }
];

// 创建控制面板
const controlPanel = document.createElement('div');
controlPanel.style.position = 'absolute';
controlPanel.style.top = '10px';
controlPanel.style.left = '10px';
controlPanel.style.zIndex = '100';
controlPanel.style.backgroundColor = 'rgba(0, 0, 0, 0.7)';
controlPanel.style.color = 'white';
controlPanel.style.padding = '10px';
controlPanel.style.borderRadius = '5px';

locations.forEach(location => {
    const button = document.createElement('button');
    button.textContent = location.name;
    button.style.margin = '5px';
    button.onclick = () => flyToLocation(location.lon, location.lat, location.height);
    controlPanel.appendChild(button);
});

document.body.appendChild(controlPanel);
